from fastapi import APIRouter, Depends
from pydantic import BaseModel
from ..utils.response_envelope import success_response
from ..utils.auth import verify_api_key

router = APIRouter()

class TelemetryRequest(BaseModel):
    equipmentId: int
    metricType: str
    value: float
    statusResult: str

@router.post("/telemetry", dependencies=[Depends(verify_api_key)])
def report_telemetry(payload: TelemetryRequest):
    return success_response(data={
        "checkId": 99012,
        "equipmentId": payload.equipmentId,
        "ticketAutoGenerated": True,
        "generatedTicketId": 1204
    })
